// Block (composition) — a centered, full-width closing call to action.
// Container caps the inner measure; consumer-supplied actions retain Component look.
import { useId, type ReactNode, type Ref } from "react";
import { Container } from "../layouts/Container";
import { Stack } from "../layouts/Stack";
import "./CtaSection.css";

export interface CtaSectionProps {
  /** Closing call-to-action heading. */
  title: string;
  /** Supporting context shown below the heading. */
  description?: string;
  /** Consumer-supplied calls to action. */
  actions?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function CtaSection({
  title,
  description,
  actions,
  className,
  ref,
}: CtaSectionProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={className ? `sd-ctasection ${className}` : "sd-ctasection"}
    >
      <Container span={8} padding="none">
        <Stack align="center" gap="small" className="sd-ctasection__content">
          {/* The name and its supporting line are ONE unit, so they group at a tighter rung than the
          section's own — otherwise the same gap separates the pair as separates it from everything
          else, and two things read as three (`PageHeader` is the reference). */}
          <Stack align="center" gap="x-small" className="sd-ctasection__heading">
            <h2 id={titleId} className="sd-ctasection__title sd-type-title-medium">{title}</h2>
            {description && (
              <p className="sd-ctasection__description sd-type-body-medium">{description}</p>
            )}
          </Stack>
          {actions}
        </Stack>
      </Container>
    </section>
  );
}

/* CtaSection.css — .sd-ctasection (Block)
   Arrangement only: full-width section rhythm and centered text. */
.sd-ctasection {
  width: 100%;
  padding-block: var(--sd-space-2x-large);
  text-align: center;
}

.sd-ctasection__title,
.sd-ctasection__description {
  margin: 0;
}

.sd-ctasection__description {
  color: var(--sd-color-text-muted);
}
